const browser = await chromium.launch();
const errors = [];
const page = await browser.newPage({viewport: {width: 1440, height: 1000}});
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(`[${m.type()}] ${m.text().slice(0, 300)}`); });
page.on('pageerror', (e) => errors.push(`[pageerror] ${e.message}`));

await page.goto(URL, {waitUntil: 'networkidle'});
await page.evaluate(() => localStorage.clear());
await page.reload({waitUntil: 'networkidle'});
await page.waitForSelector('.grid__item');
await page.waitForTimeout(400);
await page.screenshot({path: out('01-light'), fullPage: true});

// Hover the line chart to show the crosshair tooltip.
const plot = page.locator('.grid__item', {hasText: 'Сессии по платформам'}).locator('rect.viz-hit');
