// Hover a bar.
const barHit = page.locator('.grid__item', {hasText: 'Популярные страницы'}).locator('rect.viz-hit').nth(2);
const bb = await barHit.boundingBox();
await page.mouse.move(bb.x + bb.width * 0.5, bb.y + bb.height * 0.5);
await page.waitForTimeout(200);
const card = await page.locator('.grid__item', {hasText: 'Популярные страницы'}).boundingBox();
await page.screenshot({path: out('03-bar-hover'), clip: {x: card.x - 8, y: card.y - 8, width: card.width + 16, height: card.height + 16}});

// Drag "Источники трафика" to the top-left by its handle.
const handle = page.locator('.grid__item', {hasText: 'Источники трафика'}).locator('.widget__handle');
const hb = await handle.boundingBox();
await page.mouse.move(hb.x + hb.width / 2, hb.y + hb.height / 2);
await page.mouse.down();
await page.mouse.move(hb.x - 300, hb.y - 100, {steps: 10});
await page.mouse.move(hb.x - 700, hb.y - 220, {steps: 10});
await page.waitForTimeout(250);
await page.screenshot({path: out('04-dragging'), fullPage: false});
await page.mouse.up();
await page.waitForTimeout(400);
await page.screenshot({path: out('05-after-drag'), fullPage: true});

// Resize "Выручка" tile wider via the corner handle.
const resize = page.locator('.grid__item', {hasText: 'Выручка'}).locator('.grid__resize');
const rb = await resize.boundingBox();
await page.mouse.move(rb.x + rb.width / 2, rb.y + rb.height / 2);
await page.mouse.down();
await page.mouse.move(rb.x + 200, rb.y + 60, {steps: 10});
await page.mouse.up();
