node - <<'EOF'
const fs = require('fs');
const p = 'src/dashboard/widgets/StatTile.tsx';
let s = fs.readFileSync(p, 'utf8');
const rep = (a, b) => { if (!s.includes(a)) throw new Error('nf: ' + a); s = s.replace(a, b); };
rep(`const SPARK_HEIGHT = 40;
const PAD = 4;`, `const SPARK_MIN = 40;
const SPARK_MAX = 96;
const PAD = 4;`);
rep(`  const width = size.width;
  const showSpark = n > 1 && width > 40 && size.height >= SPARK_HEIGHT;
  const max = Math.max(...points, 1);
  const min = Math.min(...points, 0);
  const stepX = n > 1 ? (width - PAD * 2) / (n - 1) : 0;
  const x = (i: number) => PAD + i * stepX;
  const y = (v: number) => PAD + (SPARK_HEIGHT - PAD * 2) * (1 - (v - min) / (max - min || 1));`,
`  const width = size.width;
  // The sparkline grows with the tile but stays a sparkline, not a chart.
  const SPARK_HEIGHT = Math.max(SPARK_MIN, Math.min(SPARK_MAX, size.height));
  const showSpark = n > 1 && width > 40 && size.height >= SPARK_MIN;
  // A sparkline has no axis, so it spans the data range rather than starting at zero.
  const max = Math.max(...points);
  const min = Math.min(...points);
  const stepX = n > 1 ? (width - PAD * 2) / (n - 1) : 0;
  const x = (i: number) => PAD + i * stepX;
  const y = (v: number) => PAD + (SPARK_HEIGHT - PAD * 2) * (max === min ? 0.5 : 1 - (v - min) / (max - min));`);
fs.writeFileSync(p, s);
console.log('patched');
EOF
