// Table view of the heatmap.
await page.locator('.grid__item', {hasText: 'Активность по часам'}).locator('button[aria-label="Показать таблицу"]').click();
await page.waitForTimeout(300);
const heat = await page.locator('.grid__item', {hasText: 'Активность по часам'}).boundingBox();
