// Persistence: reload keeps the layout.
const before = await page.evaluate(() => localStorage.getItem('viz-dashboard:v1'));
await page.reload({waitUntil: 'networkidle'});
await page.waitForSelector('.grid__item');
const after = await page.evaluate(() => localStorage.getItem('viz-dashboard:v1'));
