await page.getByText('Редактирование').click();

// Reset layout.
await page.getByText('Сбросить раскладку').click();
await page.waitForTimeout(400);

// Dark theme: swap Gravity's root class on <body>.
await page.evaluate(() => { document.body.classList.remove('g-root_theme_light'); document.body.classList.add('g-root_theme_dark'); });
await page.waitForTimeout(300);
await page.screenshot({path: out('10-dark'), fullPage: true});
await page.evaluate(() => { document.body.classList.remove('g-root_theme_dark'); document.body.classList.add('g-root_theme_light'); });

// Narrow viewports.
await page.setViewportSize({width: 760, height: 900});
await page.waitForTimeout(500);
await page.screenshot({path: out('11-medium-6cols'), fullPage: true});
await page.setViewportSize({width: 420, height: 900});
await page.waitForTimeout(500);
await page.screenshot({path: out('12-stacked'), fullPage: true});

console.log('console issues:', errors.length);
for (const e of errors) console.log(e);
await browser.close();
